"""Exact ground truth. Private Harbor oracle solution."""
import sympy

FEATURES = ['p0', 'T0', 'A', 'r_p']
TARGET = 'm_dot'
PARAMETERS = {'gamma': 1.4, 'R_specific': 287.0, 'kPa_to_Pa': 1000.0, 'T_gamma_ref': 300.0, 'gamma_drop_max': 0.12, 'T_gamma_scale': 250.0, 'loss_coeff': 0.08, 'loss_exponent': 1.6, 'loss_temp_exponent': 0.5, 'poly_entropy_coeff': 0.08, 'poly_loading_exponent': 1.5, 'poly_temp_exponent': 0.5}
_symbols = {name: sympy.Symbol(name) for name in ['p0', 'T0', 'A', 'r_p', 'gamma', 'R_specific', 'kPa_to_Pa', 'T_gamma_ref', 'gamma_drop_max', 'T_gamma_scale', 'loss_coeff', 'loss_exponent', 'loss_temp_exponent', 'poly_entropy_coeff', 'poly_loading_exponent', 'poly_temp_exponent', 'm_dot']}
_expression = sympy.sympify('A*(kPa_to_Pa*p0)/sqrt(T0)*(1 - loss_coeff*(T0/T_gamma_ref)**loss_temp_exponent*(1 - r_p)**loss_exponent)*Piecewise((sqrt((2*((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) - poly_entropy_coeff*(T0/T_gamma_ref)**poly_temp_exponent*(1 - r_p)**poly_loading_exponent))/(R_specific*(((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) - poly_entropy_coeff*(T0/T_gamma_ref)**poly_temp_exponent*(1 - r_p)**poly_loading_exponent) - 1))*(r_p**(2/((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) - poly_entropy_coeff*(T0/T_gamma_ref)**poly_temp_exponent*(1 - r_p)**poly_loading_exponent)) - r_p**((((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) - poly_entropy_coeff*(T0/T_gamma_ref)**poly_temp_exponent*(1 - r_p)**poly_loading_exponent) + 1)/((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) - poly_entropy_coeff*(T0/T_gamma_ref)**poly_temp_exponent*(1 - r_p)**poly_loading_exponent)))), r_p > (2/(((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) - poly_entropy_coeff*(T0/T_gamma_ref)**poly_temp_exponent*(1 - r_p)**poly_loading_exponent) + 1))**((((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) - poly_entropy_coeff*(T0/T_gamma_ref)**poly_temp_exponent*(1 - r_p)**poly_loading_exponent))/(((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) - poly_entropy_coeff*(T0/T_gamma_ref)**poly_temp_exponent*(1 - r_p)**poly_loading_exponent) - 1))*(1 + loss_coeff*(T0/T_gamma_ref)**loss_temp_exponent*(1 - r_p)**loss_exponent)), (sqrt((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale)))/R_specific)*(2/((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) + 1))**(((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) + 1)/(2*((gamma - gamma_drop_max*(1 - exp(-(T0 - T_gamma_ref)/T_gamma_scale))) - 1))), True))', locals=_symbols)
_arguments = [_symbols[name] for name in FEATURES + list(PARAMETERS)]
_function = sympy.lambdify(_arguments, _expression, modules="numpy")

def law(rows):
    return [{TARGET: float(_function(*[float(row[name]) for name in FEATURES], *PARAMETERS.values()))} for row in rows]
